INSERT INTO `jabatan_target` (`id`, `kode_target`, `nama_target`, `deskripsi`, `kata_kunci_relevansi`, `status`, `dibuat_oleh`, `created_at`, `updated_at`) VALUES (1, 'JT-KABALAI-BP2JK-KASUBDIT-PENGADAAN', 'Kepala Balai BP2JK / Kepala Subdirektorat Direktorat Pengadaan', 'Profil jabatan sasaran suksesi gabungan untuk seluruh posisi Kepala Balai Pelaksana Pemilihan Jasa Konstruksi (BP2JK) dan Kepala Subdirektorat Pengadaan Jasa Konstruksi - mengikuti rubrik KERANGKA TALENT POOL.md', '["semua","pengadaan","barang/jasa","ppbj"]', 'NONAKTIF', 2, '2026-07-30 08:58:25', '2026-08-26 05:06:22');
INSERT INTO `jabatan_target` (`id`, `kode_target`, `nama_target`, `deskripsi`, `kata_kunci_relevansi`, `status`, `dibuat_oleh`, `created_at`, `updated_at`) VALUES (2, 'JT-DIREKTUR-PENGADAAN', 'Direktur Pengadaan Jasa Konstruksi', 'Profil jabatan sasaran suksesi jenjang JPT Pratama (Eselon II) untuk perencanaan suksesi jangka menengah-panjang Direktorat Pengadaan Jasa Konstruksi. Kandidat berasal dari jenjang Administrator (Kepala Balai/Kasubdit) yang telah memenuhi syarat pendidikan minimal S2.', '["semua","pengadaan","barang/jasa","kepemimpinan"]', 'NONAKTIF', 2, '2026-07-30 08:58:26', '2026-08-25 12:24:56');
INSERT INTO `jabatan_target` (`id`, `kode_target`, `nama_target`, `deskripsi`, `kata_kunci_relevansi`, `status`, `dibuat_oleh`, `created_at`, `updated_at`) VALUES (3, 'JT-KABALAI-BJKW', 'Kepala Balai Jasa Konstruksi Wilayah (BJKW)', 'Profil jabatan sasaran suksesi untuk seluruh posisi Kepala Balai Jasa Konstruksi Wilayah (fungsi pembinaan kompetensi & produktivitas konstruksi, berbeda dari BP2JK yang fokus pemilihan/pengadaan). Rubrik menilai kesesuaian bidang ilmu teknik/konstruksi, bukan pengadaan.', '["teknik","sipil","konstruksi","kompetensi","produktivitas"]', 'NONAKTIF', 2, '2026-07-30 08:58:26', '2026-08-25 12:24:56');
